-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (654, '11', $t$ASK 654: the Oracle takes a verse pressed against it through the four layers, and a code check sends back an answer short of its marks$t$,
  $t$The first objective of each run is why the Oracle loses rounds (the operator, 08:18 CST 2026-11-25, Wall 12065). In run 42528 the Oracle answered verses pressed against it from other rows of its chain; on W4's replay its close block on its pressed verse lacks a surrounding verse at [L1] and an [L4] line quoting the opponent. The operator, 15:17 CST: "No, you only need to Matthew 1:23 (because that's the scripture in question .. correct?) ... GO to our book Follow the Percepts and ready chapter 2." Change, five engine nodes, the Oracle seat only (Ruling 383): (1) Init with Guards: appended to GUARDHOLD, "ANSWER AT THE PRESSED VERSE", the four layers in the words of the book's chapter 2 (quoted, not reworded) and a FORM line ([L1] the pressed verse and another verse of its chapter; [L2] the Strong's number; [L3] a verse of another passage; [L4] the opponent's words, 6 or more, word for word, with their round); in the ONE-VERSE RESTRICTION paragraph "answer the pressed verse from the chain ..." becomes "take the pressed verse itself through the four layers" and "not answered from the chain" becomes "not answered through the layers"; the ASK 408 line gains "after the pressed verse's own layers". (2) D4 Build, the close message: the earlier layer sentence is replaced by the layer lines and the approved sentence. (3) Shared Library entry PRESS LAYERS (REFP + PRESS LIST + PLY), used by D3B Build and D4B Build: by code, no model call, each ANSWER block on a pressed verse is read for those marks; a block short of one joins the one existing send-back; nothing is struck. Expected effect: in the next run every Oracle answer on a pressed verse carries the marks, and the judges grade a reading of the pressed verse. The [L3] code mark (a REFP-resolved verse that is neither the pressed verse nor a verse quoted at [L1]) is the team's design, not the operator's rule. Not changed: the child, the database, any model setting, reasoning, any judge or enforcer text. (plan rev 11, ask654/w3/plan654.md md5 4a17e308)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it live" at 16:51 CST 2026-11-25 on W4's card (Wall 12241; audit 42442 by W4's post), engine a5c3001d to 5d43650d (426 nodes, connections unchanged; the child aad0ad9c unchanged by W4's post), and read back MATCH by W1 (Wall 12242: W1's fresh fetch of 5d43650d has 0 node-parameter differences against the graded b3 target 9b251b5b and against W4's fetch-back; standing 31 PASS 0 FAIL; the child not checked by W1). The words were approved by the operator in W3's thread: blocks A and B at 15:45 CST, the ASK 408 clause at 15:48 CST, the close refresh asked at 15:57 CST, "another passage" in both places at 16:05 CST. Plan rev 7b PASS (Wall 12188); build b2 PASS (Wall 12205); build b3 FAIL F1 (Wall 12235: an [L3] reference REFP cannot resolve met the mark), fixed (Wall 12237), regraded PASS WITH N1 (Wall 12240; tests 52 PASS 0 FAIL; standing 31 PASS 0 FAIL). N1: REFP resolves no book of the Apocrypha, so an [L3] line quoting only an Apocrypha verse is sent back once; told to the operator in the message above the card; ASK 658. MISTAKES: W3's plans rev 0 to 9 counted an [L3] verse only outside the pressed verse's chapter (the operator, 16:18 CST: "consider the book of Obadiah"); W3 and W4 stated that no live line told the Oracle to take a pressed verse through the layers, though the D4 Build close message had a four-layer form (W4, Wall 12192); plan rev 10 carried an [L3] code rule as settled that the operator had not chosen (16:42 CST: "i didn't choose that rule"; 16:45 CST: "that seems like a design choice to me ... not a requirement"); rev 11 records it as the team's design. Known limit: a neighbouring verse of the same chapter meets the [L3] code mark (ASK 657, a model reading, is separate and not built). IN PART, because no run has been made since the write. NOT CHECKED by W3: audit 42442; the Library Check hashes; the live engine. Open: two clean live runs; whether a judge scores the [L4] line quoting the opponent as the Oracle's own inference.$t$,
  '12065, 12176, 12187, 12188, 12192, 12195, 12199, 12202, 12205, 12225, 12226, 12228, 12232, 12233, 12234, 12235, 12237, 12240, 12241, 12242',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$In W3's thread, 2026-11-25: 15:17 CST "No, you only need to Matthew 1:23 (because that's the scripture in question .. correct?) ... GO to our book Follow the Percepts and ready chapter 2."; 15:45 CST press "Approve the words for build" (blocks A and B); 15:47 CST "you mentioned Tags earlier. Make sure tags are used, in the prompts, as you expected... do not used tags when you mean "apply the layers"."; 15:48 CST press "Add the five words"; 15:57 CST "yes, the Oracle definitely need a finale prompt (a refresh never hurts)."; 16:04 CST ""[L3] a further verse" is now "a verse of another chapter". <---- i would say "another passage" ..."; 16:05 CST press "Both places"; 16:18 CST "i would still say passage ... consider the book of Obadiah."; 16:45 CST "that seems like a design choice to me ... not a requirement". In the project chat (relayed to W3 by the coordinator): 16:14 CST "L4 is a matter of perspective ... both sides uses the layers"; 16:42 CST "i didn't choose that rule". W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo58Fxv92Xo6XyHu9T1ETyArkW): he pressed "Write it live"; the card, the message above it and the press record were read by W3 in W4's thread; the press time 16:51 CST is from the coordinator's message to W4 and Wall 12241.$t$::text),
  $j${"answer": "Write it live", "question": "Write ASK 654 (Oracle layers and its send-back check) to the live engine?", "options": {"Write it live": "I write build 9b251b5b to the engine, check it back, and W1 reads it back. The next run uses it.", "Hold": "Nothing changes; the engine stays at a5c3001d."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58Fxv92Xo6XyHu9T1ETyArkW", "press_time": "16:51 CST 2026-11-25", "message_above_the_card": "cmsg_017ZQamDMHrS6fqMHnQDVo58K5C7ZH8WgHF8e4Chfbhvru", "source": "the card, the message above it and the press record read by W3 in W4's thread by message id; press time from the coordinator's message to W4 and Wall 12241."}$j$::jsonb,
  'W3',
  $j${"md5": "4a17e3086d1a4ccaab0a9409b4d6ae82", "path": "ask654/w3/plan654.md", "note": "plan rev 11 (commit c8cebbdd). Rev 7b graded PASS by W1 (Wall 12188); rev 8 to 11 change part 1c, part 1d and PART 2 on the operator's words; build b3 was graded against rev 11 (Wall 12240). W4's check plan: ask654/w4/check_plan654.md md5 dd693785196256e1296b3ec446f4a221.", "source": "md5sum by W3; Wall 12188, 12232, 12240"}$j$::jsonb,
  $j$[{"path": "ask654/w4/b3/b654b3.cjs", "md5": "a1fa4ce79dd039ed5ef8fdd937c27578", "what": "build script, b3"}, {"path": "ask654/w4/b3/ply_lines.js", "md5": "100cad509a5737eff63ec279024f1d39", "what": "the PLY check lines (written)"}, {"path": "ask654/w4/b3/blockA.txt", "md5": "987f42ef683630bdefe99465bfe2c4c7", "what": "the approved standing words"}, {"path": "ask654/w4/b3/close1d.txt", "md5": "700ae0acebe75aa3c92c1bf478bc7423", "what": "the approved close words"}, {"path": "ask654/w4/b3/tg/target_engine_654b3.json", "md5": "9b251b5bf1bbe4c355c2368dc8863eb6", "what": "target engine (written)"}, {"path": "ask654/w4/b3/t654b3.cjs", "md5": "bdae22ca6bfa252467ff0874ca87d88e", "what": "test"}, {"path": "ask654/w4/b3/t654b3_out.txt", "md5": "d07286cbc142de5979161a7c92f85fed", "what": "test output"}, {"path": "ask654/w4/b3/r654x.cjs", "md5": "8f8899cec7c029fd22b1d76071c7a8ee", "what": "count of the [L3] mark on stored blocks"}, {"path": "ask654/w4/b3/r654x_out.txt", "md5": "e6ddaf2bd6392386a884777784927358", "what": "its output"}, {"path": "ask654/w4/write/fetchback_eng_654.json", "md5": "8214205716a3a53f5c1cf83841fa6e5c", "what": "fetch-back after the write"}, {"path": "ask654/w4/write/write654.sh", "md5": "62e4c5b5b3f72c5f132bb9fd1a1479a5", "what": "write script"}]$j$::jsonb,
  $j${"engine": "ask654/w4/write/revert_eng_654.json, md5 b73459b8258c4ddc447c18a9acf76ba3 (restores a5c3001d by W4's post)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12241; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (plan rev 7b)", "wall_id": 12188, "md5_graded": "5cadcaee", "verdict_norm": "PASS", "source": "Wall 12188"}, {"seat": "W1", "verdict": "PASS (build b2, target adef22b5)", "wall_id": 12205, "md5_graded": "adef22b5", "verdict_norm": "PASS", "source": "Wall 12205"}, {"seat": "W1", "verdict": "FAIL F1 (build b3 first target e09534f8), replaced by the regrade", "wall_id": 12235, "md5_graded": "e09534f8", "verdict_norm": "FAIL", "source": "Wall 12235"}, {"seat": "W1", "verdict": "PASS WITH N1 (build b3, target 9b251b5b, the written target)", "wall_id": 12240, "md5_graded": "9b251b5b", "verdict_norm": "PASS", "source": "Wall 12240"}, {"seat": "W1", "verdict": "PASS (written target check with the full md5, made after the write)", "wall_id": W1FULLMD5WALL, "md5_graded": "9b251b5bf1bbe4c355c2368dc8863eb6", "verdict_norm": "PASS", "source": "Wall W1FULLMD5WALL"}]$j$::jsonb,
  ARRAY['9b251b5bf1bbe4c355c2368dc8863eb6'], '[42442]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, nodes Init with Guards, D4 Build, Shared Library, D3B Build, D4B Build", "before": "version a5c3001d; the Oracle's ONE-VERSE RESTRICTION paragraph said to answer the pressed verse from the chain; the close message said \"Under each ANSWER line write the four layers, each on its own line with its tag: ...\"; no check of the layer marks on an answer to a pressed verse", "after": "version 5d43650d-afe3-446f-a7c3-8605021b03dc, 426 nodes, connections unchanged; GUARDHOLD carries ANSWER AT THE PRESSED VERSE, the four layer lines and the FORM line; the ONE-VERSE RESTRICTION paragraph and the ASK 408 line as approved; the close message carries the layer lines and the approved sentence; Shared Library entry PRESS LAYERS = REFP + PRESS LIST + PLY (LIB lines 3883 to 3909, n 13,717) used by D3B Build and D4B Build; library fb8658437cad8fbf, map 2baa80e9e6217752 (W4, Wall 12241)"}]$j$::jsonb,
  $j$[{"name": "t654b3.cjs on the written target", "result": "52 PASS, 0 FAIL (output d07286cb): the form block gives 0 items; W1's cases (a) to (g) of Wall 12233; the F1 probe (an unresolvable [L3] reference lacks the mark); Obadiah, another passage of the one chapter passes; an adjacent verse passes (the known limit); the stored replays unchanged (42528 15 of 15, 42517 17 of 17, 42373 31 of 31 listed)", "source": "ask654/w4/b3/t654b3_out.txt (tail read by W3); Wall 12234, 12237; rerun by W1, Wall 12240"}, {"name": "r654x.cjs, the [L3] mark on stored blocks", "result": "58 pressed-verse blocks of 42528, 42517 and 42373: the chapter rule lists 3, the written rule 0", "source": "Wall 12217 by plan rev 10; ask654/w4/b3/r654x_out.txt not read by W3"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W1, Wall 12240), before and after the write (W4, Wall 12241) and on live (W1, Wall 12242); pair Library Check PASSES; one-copy check PASS", "source": "Wall 12240, 12241, 12242"}, {"name": "NOT RUN", "result": "any live call", "source": "Wall 12241"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (W1's fresh fetch of live 5d43650d: 426 nodes, 0 node-parameter differences against the graded b3 target 9b251b5b and against W4's fetch-back, connections equal; standing 31 PASS 0 FAIL; the child not fetched by W1)", "wall_id": 12242, "source": "Wall 12242"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "in every Oracle link round and close, each pressed verse has an ANSWER head and, in its block, [L1] the verse and another verse of its chapter quoted, [L2] a Strong's number, [L3] a verse of another passage quoted, [L4] the opponent's words quoted with their round; a round sent back carries PRESSED VERSES SHORT OF THEIR LAYERS naming each verse and its lack; the close request carries the layer lines.", "not_shown": "the send-back on a live run; how a judge scores the [L4] line quoting the opponent; an Apocrypha [L3] line.", "source": "Wall 12241, 12242; plan rev 11"}$j$::jsonb,
